function bellman(n, edges, src){
  var dist=new Array(n).fill(Infinity); dist[src]=0;
  for(var i=0;i<n-1;i++){ var updated=false;
    for(var e=0;e<edges.length;e++){ var u=edges[e][0],v=edges[e][1],w=edges[e][2];
      if(dist[u]!==Infinity && dist[u]+w<dist[v]){ dist[v]=dist[u]+w; updated=true; } }
    if(!updated) break; }
  var neg=false;
  for(var e=0;e<edges.length;e++){ var u=edges[e][0],v=edges[e][1],w=edges[e][2];
    if(dist[u]!==Infinity && dist[u]+w<dist[v]){ neg=true; break; } }
  return {dist:dist, negativeCycle:neg};
}
var EXPORTS={bellman:bellman};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BellmanFordForgePure = EXPORTS; }
